const VIJAYANAGARA_STATS=[{label:"Rulers Featured",value:"5"},{label:"Gold Coins",value:"10"},{label:"Time Span",value:"~310 Years"},{label:"Scripts",value:"Kannada, Nagari"}],VIJAYANAGARA_RULERS=[{id:"harihara1",name:"Harihara I",period:"1336 – 1356 CE",blurb:"Co-founder of the Vijayanagara Empire with his brother Bukka Raya I, establishing the capital on the Tungabhadra river and issuing the empire's earliest gold Pagodas.",territoryNote:"Tungabhadra basin, Deccan Plateau"},{id:"bukka1",name:"Bukka Raya I",period:"1356 – 1377 CE",blurb:"Consolidated the fledgling empire, standardised the gold Varaha/Pagoda weight standard, and expanded coinage bearing Shaiva imagery across the growing realm.",territoryNote:"Karnataka to northern Tamil Nadu"},{id:"devaraya2",name:"Deva Raya II",period:"1424 – 1446 CE",blurb:"Known as 'Gajabetekara' (elephant hunter), he expanded trade contacts with the Persian Gulf and Southeast Asia, boosting gold coin output and circulation.",territoryNote:"Deccan to the southern coasts"},{id:"krishnadevaraya",name:"Krishnadevaraya",period:"1509 – 1529 CE",blurb:"The empire's greatest ruler and patron of arts and temples; his Balakrishna Pagoda became the most recognisable and widely imitated gold coin of medieval South India.",territoryNote:"Peak extent: Deccan, Tamil country, Odisha frontier"},{id:"achyutaraya",name:"Achyuta Raya",period:"1529 – 1542 CE",blurb:"Crowned at Tirupati, he continued the Balakrishna and Venkateshwara coin types, closely tying the empire's currency to its major temple patronage.",territoryNote:"Deccan and Tamil country, contracting frontiers"}],VIJAYANAGARA_COINS=[{id:"harihara1-garuda-varaha",rulerId:"harihara1",coinType:"Garuda Varaha (Gold Pagoda)",metal:"Gold",denomination:"Varaha / Pagoda",script:"Nagari & Kannada",circulation:"Tungabhadra region",obverse:{desc:"Garuda, the mythical eagle and vehicle of Vishnu, shown standing frontally with wings displayed — one of the earliest royal emblems adopted by the new dynasty.",hotspots:[{x:50,y:38,label:"Garuda Figure",note:"A Vaishnava emblem signalling royal legitimacy and divine protection for the newly founded dynasty."},{x:50,y:70,label:"Beaded Border",note:"A dotted rim framing the design, a common South Indian minting convention of the period."}]},reverse:{desc:"A Nagari legend reading 'Sri Harihara' across the field, flanked by dots, identifying the issuing king.",hotspots:[{x:50,y:50,label:"Royal Legend",note:"Names the king directly in Nagari script, a practice continued by nearly every later Vijayanagara ruler."}]},history:"Struck within a few decades of the empire's founding in 1336 CE, this Garuda type reflects Harihara I's early affirmation of Vaishnava kingship at a moment when the dynasty was still establishing its authority on the Tungabhadra frontier."},{id:"harihara1-hanuman-gadyana",rulerId:"harihara1",coinType:"Hanuman Type Gadyana",metal:"Gold",denomination:"Gadyana",script:"Kannada",circulation:"Deccan Plateau",obverse:{desc:"Hanuman shown seated in devotional pose, hands folded, a motif drawn from the region's strong Rama-bhakti tradition.",hotspots:[{x:50,y:42,label:"Seated Hanuman",note:"Reflects the popularity of devotional Vaishnava figures on early Vijayanagara coin dies."}]},reverse:{desc:"A short Kannada legend naming the ruler, set within a plain circular field.",hotspots:[{x:50,y:50,label:"Kannada Legend",note:"One of the earliest uses of Kannada script on Vijayanagara gold, alongside Nagari issues."}]},history:"The Gadyana denomination carried over older South Indian weight conventions, showing how the new empire's coinage grew out of, rather than replaced, existing regional currency systems."},{id:"bukka1-umamaheshwara",rulerId:"bukka1",coinType:"Umamaheshwara Pagoda",metal:"Gold",denomination:"Varaha / Pagoda",script:"Kannada & Nagari",circulation:"Karnataka to northern Tamil country",obverse:{desc:"Shiva and Parvati seated together on the bull Nandi, a devotional Shaiva composition known as the Umamaheshwara type.",hotspots:[{x:44,y:45,label:"Shiva & Parvati",note:"Marks Bukka Raya I's public patronage of Shaiva worship alongside the dynasty's earlier Vaishnava emblems."},{x:60,y:68,label:"Nandi Bull",note:"Shiva's mount, anchoring the pair firmly within Shaiva iconographic convention."}]},reverse:{desc:"A Kannada legend reading 'Sri Bukka Raya' across three lines, the standard reverse format for this issue.",hotspots:[{x:50,y:50,label:"Three-Line Legend",note:"This three-line Kannada legend format became a template copied by several later rulers' coinage."}]},history:"Bukka Raya I's reign saw the gold Varaha standardised at roughly 52 grains, a weight so consistent that it was imitated by South Indian kingdoms for the next three centuries, long after Vijayanagara itself had fallen."},{id:"bukka1-boar-type",rulerId:"bukka1",coinType:"Boar (Varaha) Type",metal:"Gold",denomination:"Varaha",script:"Kannada",circulation:"Deccan Plateau",obverse:{desc:"The dynastic boar (Varaha) emblem, an incarnation of Vishnu, shown walking with sun and crescent moon symbols above.",hotspots:[{x:50,y:40,label:"Varaha Emblem",note:"Gave the coin denomination its lasting name — 'Varaha' — used across South India long after the empire's fall."},{x:68,y:24,label:"Sun & Moon",note:"A common royal motif in South Indian coinage, symbolising the ruler's claim to endure 'as long as the sun and moon'."}]},reverse:{desc:"A dagger and Kannada legend naming the king, set within a beaded circular border.",hotspots:[{x:50,y:55,label:"Dagger Symbol",note:"A martial emblem occasionally paired with royal legends on Vijayanagara gold."}]},history:"This is the type that gave the entire Vijayanagara gold denomination its enduring name — the Varaha — which remained in use as a unit of account in South India well into the colonial period."},{id:"devaraya2-elephant-gadyana",rulerId:"devaraya2",coinType:"Elephant Type Gadyana",metal:"Gold",denomination:"Gadyana",script:"Nagari",circulation:"Deccan to southern ports",obverse:{desc:"A caparisoned elephant walking right, referencing Deva Raya II's title 'Gajabetekara' (elephant hunter).",hotspots:[{x:50,y:45,label:"Royal Elephant",note:"Directly references the king's personal title and his renowned mastery of elephant warfare."}]},reverse:{desc:"A Nagari legend naming the ruler, framed by a plain dotted border.",hotspots:[{x:50,y:50,label:"Nagari Legend",note:"Nagari remained in parallel use alongside Kannada throughout the empire's coinage history."}]},history:"Deva Raya II's reign expanded Vijayanagara's maritime trade with the Persian Gulf and Southeast Asia, and surviving foreign travellers' accounts describe large quantities of these gold coins circulating in Indian Ocean ports."},{id:"devaraya2-sun-moon-varaha",rulerId:"devaraya2",coinType:"Sun-Moon Varaha",metal:"Gold",denomination:"Varaha",script:"Kannada",circulation:"Southern Deccan",obverse:{desc:"The dynastic boar emblem beneath a prominent sun and crescent moon, a refined continuation of Bukka Raya I's boar type.",hotspots:[{x:50,y:48,label:"Boar with Sun & Moon",note:"Continuity of dynastic emblem design across nearly a century, reinforcing visual continuity of royal authority."}]},reverse:{desc:"A Kannada legend reading 'Sri Deva Raya' in three lines.",hotspots:[{x:50,y:50,label:"Ruler's Name",note:"Confirms the issuing king and helps numismatists date coin hoards found across the Deccan."}]},history:"Coin hoards from this period, found as far as Sri Lanka and the Malabar coast, testify to the wide circulation of Vijayanagara gold during Deva Raya II's active trading reign."},{id:"krishnadevaraya-balakrishna",rulerId:"krishnadevaraya",coinType:"Balakrishna Pagoda",metal:"Gold",denomination:"Varaha / Pagoda",script:"Kannada",circulation:"Empire-wide, peak extent",obverse:{desc:"The infant Krishna (Balakrishna) crawling, holding a ball of butter — the empire's most iconic and widely copied coin design.",hotspots:[{x:46,y:55,label:"Crawling Balakrishna",note:"Became the single most recognisable Vijayanagara coin type, imitated by successor Nayak kingdoms for centuries after 1565."},{x:62,y:48,label:"Butter Ball",note:"References the popular Krishna-Leela devotional stories widely celebrated under Krishnadevaraya's rule."}]},reverse:{desc:"A three-line Kannada legend reading 'Sri Krishnaraya', the king's regnal name.",hotspots:[{x:50,y:50,label:"Sri Krishnaraya Legend",note:"One of the most commonly found legends in Vijayanagara-era gold hoards, reflecting the huge volume minted."}]},history:"Krishnadevaraya's reign (1509–1529) is regarded as the empire's golden age. The Balakrishna Pagoda was minted in enormous quantities to fund temple grants, military campaigns, and public works, and its design was so influential that later Nayak rulers of Madurai and Tanjore continued striking near-identical coins long after Vijayanagara's political power ended."},{id:"krishnadevaraya-two-figure",rulerId:"krishnadevaraya",coinType:"Two-Figure (Lakshmi-Narasimha) Type",metal:"Gold",denomination:"Varaha / Pagoda",script:"Kannada",circulation:"Empire-wide",obverse:{desc:"Two seated deity figures — Lakshmi and Narasimha — a composition celebrating the ruler's devotion to Vishnu's man-lion incarnation.",hotspots:[{x:50,y:45,label:"Lakshmi-Narasimha Pair",note:"Reflects Krishnadevaraya's personal devotion, recorded in his patronage of the Lakshmi-Narasimha shrine at Hampi."}]},reverse:{desc:"A Kannada legend including the royal motto 'Kannada Rajya Ramaramana', asserting the king's sovereignty.",hotspots:[{x:50,y:52,label:"Royal Motto",note:"A rare instance of an explicit royal motto, rather than just a name, appearing on Vijayanagara gold."}]},history:"This type illustrates how Krishnadevaraya used coin iconography to publicly link his rule to specific temple patronage projects at the capital, Hampi, reinforcing the connection between religious merit and royal legitimacy."},{id:"achyutaraya-venkateshwara",rulerId:"achyutaraya",coinType:"Venkateshwara Type",metal:"Gold",denomination:"Varaha / Pagoda",script:"Kannada",circulation:"Tirupati region and empire-wide",obverse:{desc:"Lord Venkateshwara (Balaji) standing in blessing pose, reflecting the deep royal ties to the Tirupati temple where Achyuta Raya was crowned.",hotspots:[{x:50,y:40,label:"Venkateshwara",note:"Directly ties the coinage to Achyuta Raya's coronation at the Tirupati temple in 1529 CE."}]},reverse:{desc:"A Kannada legend reading 'Sri Achyuta Raya' across the field.",hotspots:[{x:50,y:50,label:"Ruler's Legend",note:"Distinguishes this issue from the earlier Balakrishna coinage struck under Krishnadevaraya."}]},history:"Achyuta Raya's coronation at Tirupati, an unusual departure from the traditional Hampi coronation site, is directly reflected in this coin type honouring the temple's presiding deity."},{id:"achyutaraya-balakrishna-cont",rulerId:"achyutaraya",coinType:"Balakrishna Continuation Type",metal:"Gold",denomination:"Varaha / Pagoda",script:"Kannada",circulation:"Empire-wide",obverse:{desc:"The crawling infant Krishna motif retained from Krishnadevaraya's reign, with minor stylistic variation in the border design.",hotspots:[{x:50,y:52,label:"Retained Balakrishna Motif",note:"Shows how popular and trusted coin designs were deliberately continued across reigns to maintain public confidence in the currency."}]},reverse:{desc:"A Kannada legend naming Achyuta Raya, following the same three-line format used by his predecessor.",hotspots:[{x:50,y:50,label:"Continuity Legend",note:"Demonstrates administrative continuity in the imperial mint even after a change of ruler."}]},history:"The persistence of the Balakrishna design under Achyuta Raya highlights how deeply the type had become associated with trustworthy Vijayanagara gold in regional and maritime trade networks."}],VIJAYANAGARA_TIMELINE=[{year:"1336 CE",title:"Founding of the Empire",desc:"Harihara I and Bukka Raya I establish Vijayanagara on the Tungabhadra river, issuing the earliest gold Pagodas."},{year:"1356 CE",title:"Bukka Raya I standardises the Varaha",desc:"The gold Varaha/Pagoda weight standard (~52 grains) is fixed, later imitated across South India for centuries."},{year:"1424 CE",title:"Deva Raya II expands trade",desc:"Maritime trade with the Persian Gulf and Southeast Asia grows, boosting gold coin circulation in Indian Ocean ports."},{year:"1509 CE",title:"Krishnadevaraya's golden age begins",desc:"The Balakrishna Pagoda becomes the empire's standard gold coin, minted in vast quantities to fund temples and campaigns."},{year:"1529 CE",title:"Achyuta Raya crowned at Tirupati",desc:"Coinage introduces the Venkateshwara type while continuing the trusted Balakrishna design."},{year:"1565 CE",title:"Battle of Talikota",desc:"Defeat by the Deccan Sultanates breaks Vijayanagara's political power, though its Varaha weight standard survives in successor Nayak kingdoms."}],VIJAYANAGARA_TERRITORY=[{id:"hampi",region:"Hampi (Vijayanagara Capital)",note:"The empire's principal mint on the Tungabhadra river, striking the majority of gold Pagodas.",x:46,y:44},{id:"penukonda",region:"Penukonda",note:"A secondary capital and mint city, especially important after 1565 CE.",x:58,y:58},{id:"udayagiri",region:"Udayagiri",note:"A key eastern fort and mint town on the frontier with the Gajapati kingdom of Odisha.",x:72,y:50},{id:"chandragiri",region:"Chandragiri",note:"Later served as a regional capital, close to Tirupati, with its own coin issues.",x:64,y:68},{id:"gutti",region:"Gutti (Gooty)",note:"A fortified mint town controlling routes across the southern Deccan.",x:55,y:52},{id:"tirupati",region:"Tirupati",note:"Temple town closely tied to Venkateshwara-type coinage and royal coronations.",x:66,y:74}],VIJAYANAGARA_REFERENCES=[{text:"Elliot, Walter. Coins of Southern India. Trübner & Co., 1886.",url:"https://www.britishmuseum.org/collection"},{text:"Mitchiner, Michael. The Coinage and History of Southern India. Hawkins Publications, 1998.",url:"https://numismatics.org/"},{text:"Rangachari, K. Coins of the Vijayanagara Dynasty — Madras Government Museum Bulletin.",url:"https://www.jstor.org/"},{text:"American Numismatic Society — South Indian Coin Collection Records.",url:"https://numismatics.org/"}];"undefined"!=typeof module&&module.exports&&(module.exports={VIJAYANAGARA_STATS:VIJAYANAGARA_STATS,VIJAYANAGARA_RULERS:VIJAYANAGARA_RULERS,VIJAYANAGARA_COINS:VIJAYANAGARA_COINS,VIJAYANAGARA_TIMELINE:VIJAYANAGARA_TIMELINE,VIJAYANAGARA_TERRITORY:VIJAYANAGARA_TERRITORY,VIJAYANAGARA_REFERENCES:VIJAYANAGARA_REFERENCES});